 "initial_node": "setup",
 "system_prompt": "You are Ostral Bank's automated assistant, calling a customer. Speak English, one or two short sentences per turn. Before identity is verified, never say 'arrears', 'debt', 'payment', 'overdue' or name the product, to anyone. Never invent amounts, dates, figures or reasons: if the tools and facts do not give an answer, say you do not have that information. Never offer a discount, a waiver, an instalment plan or any term not given to you. Never ask how much the customer can pay. If asked whether you are a robot or an AI, say you are Ostral Bank's automated assistant and continue. If asked whether this is a scam, say they can hang up and call Ostral Bank on the number printed on their statement, and continue. If the customer asks for a human, first ask once whether you can help. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
 "test_variables": {
  "customer_id": "c_91ab00",
  "first_name": "Hannah",
  "last_name": "Moreau",
  "title": "Ms",
  "now": "2026-11-04T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "opening",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = set(datetime.date.fromisoformat(h) for h in ['2026-11-09', '2026-11-23', '2026-12-08', '2026-12-25', '2026-12-28'])\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_bd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef next_bd(d):\n    d = d + datetime.timedelta(days=1)\n    while not is_bd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\nvars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\nvars['call_state'] = 'open'\nvars['promise_count'] = '0'\nvars['id_state'] = 'open'\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    nxt = next_bd(today)\n    hm = now.strftime('%H:%M')\n    parts = []\n    if hm < '20:00':\n        parts.append('today, ' + spoken(today) + ' (date ' + today.isoformat() + '), at a time later than ' + hm + ' and between 10:00 and 20:00')\n    parts.append(spoken(nxt) + ' (date ' + nxt.isoformat() + '), between 10:00 and 20:00')\n    vars['callback_window_text'] = 'A callback can only be booked ' + ', or '.join(parts) + '. 10:00 and 20:00 are both allowed. Now it is ' + spoken(today) + ', ' + hm + '.'\n    vars['calendar_state'] = 'ok'\nexcept Exception:\n    vars['callback_window_text'] = 'A callback can only be booked today or the next business day, between 10:00 and 20:00.'\n    vars['calendar_state'] = 'error'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "opening", "description": "always", "condition": {"operator": "always"}}]
  },
  "opening": {
   "name": "opening",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Hello, I am Ostral Bank's automated assistant. This call is recorded for quality and security. Am I speaking with {{title}} {{last_name}}?"},
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only 'yes', 'that's me', 'speaking' or the customer's own name confirms it; 'hello', 'go ahead' and 'who is this' do not. If it is unclear, answer any question first, then ask once more: \"Am I speaking with {{title}} {{last_name}}?\". Say nothing about why you are calling. If they ask for a human, first ask once whether you can help. Call end_call only right after you said goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "who", "type": "string", "enum_values": ["stay", "customer", "someone_else", "wrong_number", "deceased", "still_unclear", "declined", "human"],
     "description": "customer: a clear yes, 'that's me', 'speaking' or their own name. someone_else: another person answered. wrong_number: the number does not belong to the customer. deceased: the customer has died. still_unclear: still no clear answer after you asked a second time. declined: they said twice they do not want to talk. human: they insist on a person after you asked once whether you can help. Else stay.",
     "min_confidence": 0.6}
   ],
   "max_node_turns": 4,
   "max_turn_transition": "goodbye_short",
   "transitions": [
    {"target_node": "identity", "description": "The customer confirmed", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "customer"}]}},
    {"target_node": "third_party_prep", "description": "Someone else answered", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "someone_else"}]}},
    {"target_node": "mark_wrong_number", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "wrong_number"}]}},
    {"target_node": "mark_deceased", "description": "The customer has died", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "goodbye_short", "description": "Still unclear after the second ask", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "still_unclear"}]}},
    {"target_node": "mark_declined", "description": "Does not want to talk", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "declined"}]}},
    {"target_node": "transfer_human", "description": "Insists on a person", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "human"}]}}
   ]
  },
  "mark_wrong_number": {
   "name": "mark_wrong_number",
   "node_type": "code",
