    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one answer. CALL it every time the customer answers a security question.", "parameters": {"type": "object", "properties": {
