    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = set(datetime.date.fromisoformat(h) for h in ['2026-11-09', '2026-11-23', '2026-12-08', '2026-12-25', '2026-12-28'])\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_bd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef next_bd(d):\n    d = d + datetime.timedelta(days=1)\n    while not is_bd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(v):\n    return '{:,.2f}'.format(float(v))\n\ndef resolve(text, today):\n    s = str(text or '').strip().lower()\n    if not s:\n        return None\n    m = re.search(r'(\\d{4})-(\\d{1,2})-(\\d{1,2})', s)\n    if m:\n        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))\n    m = re.search(r'\\b(\\d{1,2})[./](\\d{1,2})(?:[./](\\d{2,4}))?\\b', s)\n    if m:\n        y = int(m.group(3)) if m.group(3) else today.year\n        y = y + 2000 if y < 100 else y\n        return datetime.date(y, int(m.group(2)), int(m.group(1)))\n    for i, name in enumerate(MONTHS):\n        m = re.search(r'\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?' + name[:3], s) or re.search(name[:3] + r'[a-z]*\\s+(?:the\\s+)?(\\d{1,2})', s)\n        if m:\n            c = datetime.date(today.year, i + 1, int(m.group(1)))\n            return c if c >= today else datetime.date(today.year + 1, i + 1, int(m.group(1)))\n    m = re.search(r'\\b(\\d{1,2})(?:st|nd|rd|th)\\b', s)\n    if m:\n        day = int(m.group(1))\n        for k in range(3):\n            y, mo = today.year + (today.month - 1 + k) // 12, (today.month - 1 + k) % 12 + 1\n            try:\n                c = datetime.date(y, mo, day)\n            except ValueError:\n                continue\n            if c >= today:\n                return c\n        return None\n    if 'day after tomorrow' in s:\n        return today + datetime.timedelta(days=2)\n    if 'tomorrow' in s:\n        return today + datetime.timedelta(days=1)\n    if re.search(r'\\btoday\\b', s):\n        return today\n    mon = today - datetime.timedelta(days=today.weekday())\n    for i, name in enumerate(WEEKDAYS):\n        if name in s:\n            if 'next ' + name in s:\n                return mon + datetime.timedelta(days=7 + i)\n            d = mon + datetime.timedelta(days=i)\n            if 'this ' + name in s:\n                return d\n            return d if d >= today else d + datetime.timedelta(days=7)\n    return None\n\ndef offer(kind, text, amount, day):\n    vars['offer_kind'] = kind\n    vars['offer_text'] = text\n    vars['offer_amount'] = str(round(float(amount), 2))\n    vars['offer_date'] = day.isoformat()\n    vars['eval_state'] = 'offer'\n\ndef close(outcome, reason):\n    vars['close_outcome'] = outcome\n    vars['close_reason'] = reason\n    vars['eval_state'] = 'close'\n\ntry:\n    today = parse_now(vars.get('now')).date()\n    past_due = float(vars.get('past_due') or 0)\n    floor = float(vars.get('floor') or 0)\n    deadline = datetime.date.fromisoformat(vars.get('deadline'))\n    attempt1 = datetime.date.fromisoformat(vars.get('attempt1'))\n    name = str(vars.get('product_name') or '')\n    cur_amount = float(vars.get('offer_amount') or past_due)\n    cur_date = datetime.date.fromisoformat(vars.get('offer_date') or today.isoformat())\n    kind = str(vars.get('offer_kind') or 'first')\n    ans = str(vars.get('neg_answer') or 'stay')\n    raw = str(vars.get('cust_amount') or '').strip().replace(',', '')\n    try:\n        amt = float(raw) if raw not in ('', 'None', 'null') else None\n    except ValueError:\n        amt = None\n    words = str(vars.get('cust_date_words') or '').strip()\n    if words in ('None', 'null'):\n        words = ''\n\n    def refusal():\n        if vars.get('hardship') == 'yes':\n            close('no_promise', 'hardship')\n            return\n        refused = str(vars.get('refused_offers') or '')\n        if kind != 'ask_day':\n            refused = refused + '|' + str(vars.get('offer_amount')) + '@' + str(vars.get('offer_date'))\n        vars['refused_offers'] = refused\n        used = int(vars.get('attempts_used') or 0)\n        mx = int(vars.get('attempts_max') or 1)\n        while used < mx:\n            used += 1\n            if used == 1:\n                a = floor if vars.get('too_much') == 'yes' else past_due\n                d = attempt1\n            else:\n                a, d = floor, deadline\n            if (str(round(float(a), 2)) + '@' + d.isoformat()) in refused:\n                continue\n            vars['attempts_used'] = str(used)\n            text = 'Could you pay ' + money(a) + ' on ' + spoken(d) + '?'\n            if a < past_due:\n                text = text + ' The rest stays overdue.'\n            offer('attempt', text, a, d)\n            return\n        vars['attempts_used'] = str(used)\n        close('no_promise', 'refused')\n\n    def validate(amount, day):\n        amount = min(float(amount), past_due)\n        if day is None:\n            if vars.get('vague_asked') != 'yes':\n                vars['vague_asked'] = 'yes'\n                offer('ask_day', 'Which exact day could you make the payment?', amount, cur_date)\n                return\n            offer('deadline', 'Then I propose ' + spoken(deadline) + ', the latest date I can record. Could you pay ' + money(amount) + ' on that day?', amount, deadline)\n            return\n        if day < today:\n            offer('ask_day', 'I can only record a date from today on. Which day could you make the payment?', amount, cur_date)\n            return\n        if day > deadline:\n            offer('deadline', 'The latest date I can record is ' + spoken(deadline) + '. Could you pay ' + money(amount) + ' on that day?', amount, deadline)\n            return\n        if not is_bd(day):\n            nb = min(next_bd(day), deadline)\n            offer('date', spoken(day) + ' is not a business day. Could you pay ' + money(amount) + ' on ' + spoken(nb) + ' instead?', amount, nb)\n            return\n        if amount < floor - 0.001:\n            vars['floor_offered'] = 'yes'\n            offer('floor', 'I cannot record ' + money(amount) + '. The lowest amount I can record is ' + money(floor) + ', and the rest stays overdue. Could you pay ' + money(floor) + ' on ' + spoken(day) + '?', floor, day)\n            return\n        vars['rec_amount'] = round(amount, 2)\n        vars['rec_date'] = day.isoformat()\n        offer('readback', 'So that is ' + money(amount) + ' for your ' + name + ', on ' + spoken(day) + '. Do you confirm?', amount, day)\n\n    if ans == 'accept' and kind == 'readback' and amt is None and not words:\n        vars['record_tries'] = '0'\n        vars['record_result'] = 'none'\n        vars['eval_state'] = 'record'\n    elif ans == 'refused':\n        refusal()\n    elif ans == 'too_much' and amt is None:\n        vars['too_much'] = 'yes'\n        if vars.get('floor_offered') != 'yes':\n            vars['floor_offered'] = 'yes'\n            offer('floor', 'I understand. I can record a lower amount of ' + money(floor) + '; the rest stays overdue. Could you pay ' + money(floor) + ' on ' + spoken(cur_date) + '?', floor, cur_date)\n        else:\n            refusal()\n    elif ans in ('accept', 'proposal', 'too_much'):\n        a = amt if amt is not None else cur_amount\n        if words:\n            d = resolve(words, today)\n        elif kind == 'ask_day':\n            d = None\n        else:\n            d = cur_date\n        validate(a, d)\n    else:\n        vars['eval_state'] = 'offer'\nexcept Exception:\n    vars['eval_state'] = 'offer'\nvars['neg_answer'] = 'stay'\nvars['cust_amount'] = ''\nvars['cust_date_words'] = ''\n"},
