        "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD. postcode: capitals, one space before the last three characters, e.g. LS6 2HQ. phone_last4: four digits.", "default": "{{answer}}"}},
       "required": ["customer_id", "field", "answer"]}}}},
     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        f = b.get('field')\n        a = str(b.get('answer') or '').strip()\n        if f == 'postcode':\n            p = a.upper().replace(' ', '')\n            if len(p) > 3:\n                a = p[:-3] + ' ' + p[-3:]\n        elif f == 'phone_last4':\n            dg = ''.join(c for c in a if c.isdigit())\n            if len(dg) >= 4:\n                a = dg[-4:]\n        elif f == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                a = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\n        b['answer'] = a\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'All questions passed. Say thank you in a few words.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the date of birth again with the month as a word. This does not count as a wrong answer.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Do not mention any account.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Ask the next question: after the date of birth the postcode of the registered address; after the postcode the last four digits of the phone number on file.'\n        elif str(d.get('ok')).lower() == 'false':\n            d['what_to_do_next'] = 'The answer could not be read. Ask for the same answer again.'\n        else:\n            d['what_to_do_next'] = 'That answer is wrong. Ask the same question once more.'\n    else:\n        result['what_to_do_next'] = 'The check did not work. Ask the same question again.'\nexcept Exception:\n    pass\n"},
