    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\nimport json\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nHOL = set(datetime.date.fromisoformat(h) for h in ['2026-11-09', '2026-11-23', '2026-12-08', '2026-12-25', '2026-12-28'])\nBANDS = [(1, 14, 10, 1), (15, 60, 5, 2)]\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_bd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef next_bd(d):\n    d = d + datetime.timedelta(days=1)\n    while not is_bd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef add_bd(d, n):\n    for _ in range(n):\n        d = next_bd(d)\n    return d\n\ndef last_bd_of_week(d):\n    mon = d - datetime.timedelta(days=d.weekday())\n    day = mon + datetime.timedelta(days=4)\n    while day >= mon:\n        if is_bd(day):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef spoken(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(v):\n    return '{:,.2f}'.format(float(v))\n\ndef as_list(value):\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\n\ndef list_from_vars(vars, name, prefixes):\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = {}\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            rest = str(key)[len(start):]\n            idx, _, field = rest.partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), {})[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\n\ntry:\n    today = parse_now(vars.get('now')).date()\n    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    p = items[0]\n    t = str(p.get('type') or '')\n    if t == 'credit_card':\n        name = 'credit card ending ' + str(p.get('card_last4') or '')\n        floor = float(p.get('minimum_payment') or 0)\n    else:\n        name = 'car loan' if t == 'car_loan' else 'personal loan'\n        floor = float(p.get('instalment_amount') or 0)\n    past_due = float(p.get('past_due') or 0)\n    days = int(float(p.get('days_late') or 0))\n    band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])\n    deadline = add_bd(today, band[2])\n    week_end = last_bd_of_week(today)\n    if week_end is None or week_end <= today:\n        week_end = last_bd_of_week(today + datetime.timedelta(days=7))\n    attempt1 = min(week_end, deadline)\n    pay_today = today if is_bd(today) else next_bd(today)\n    vars['product_id'] = str(p.get('product_id') or '')\n    vars['product_name'] = name\n    vars['past_due'] = str(past_due)\n    vars['floor'] = str(floor)\n    vars['deadline'] = deadline.isoformat()\n    vars['attempt1'] = attempt1.isoformat()\n    vars['attempts_max'] = str(band[3])\n    vars['attempts_used'] = '0'\n    vars['too_much'] = 'no'\n    vars['floor_offered'] = 'no'\n    vars['vague_asked'] = 'no'\n    vars['hardship'] = 'no'\n    vars['refused_offers'] = ''\n    vars['statement_text'] = 'I am calling from the collections team about a late payment on your ' + name + '. The past-due amount is ' + money(past_due) + ', and it is ' + str(days) + ' days late.'\n    vars['facts_text'] = ('Today is ' + spoken(today) + ' (' + today.isoformat() + '). Product: ' + name + '. Past due: ' + money(past_due) + '. Days late: ' + str(days) +\n                          '. Lowest amount that can be recorded: ' + money(floor) + '. Latest date that can be recorded: ' + spoken(deadline) + ' (' + deadline.isoformat() + '). Business days are Monday to Friday except bank holidays 2026-11-09, 2026-11-23, 2026-12-08, 2026-12-25, 2026-12-28.')\n    vars['offer_kind'] = 'first'\n    vars['offer_text'] = vars['statement_text'] + ' Can you make this payment today?'\n    vars['offer_amount'] = str(round(past_due, 2))\n    vars['offer_date'] = pay_today.isoformat()\n    vars['neg_answer'] = 'stay'\n    vars['close_outcome'] = 'no_promise'\n    vars['close_reason'] = 'refused'\n    vars['facts_state'] = 'ok'\nexcept Exception:\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['facts_state'] = 'error'\n"},
