  "third_party": {
   "name": "third_party",
   "node_type": "conversation",
   "task_message": "You are not speaking with {{title}} {{last_name}}. Do not say why you are calling and say nothing about any account, even if the person offers to pay or to answer questions. Ask when {{title}} {{last_name}} can be reached. {{callback_window_text}} When the person gives a day and time inside that window, call schedule_callback with date (YYYY-MM-DD) and time (HH:MM). If the time is outside the window, ask once for another time; if the second one is also outside, do not schedule, thank them and say goodbye. If they say the customer has died, say only \"I am sorry for your loss.\" and nothing else. After every tool result, either speak or call the next tool. Call end_call only right after you said goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "schedule_callback", "handler": "__function__:api_call", "description": "Book the callback. CALL it as soon as the person gives a day and time inside the window.", "parameters": {"type": "object", "properties": {
      "url": {"type": "string", "default": "https://bank-mock.invalid/f2-ostral/v1/schedule_callback"},
      "method": {"type": "string", "default": "POST"},
      "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
      "body": {"type": "object", "properties": {
        "customer_id": {"type": "string", "default": "{{customer_id}}"},
        "date": {"type": "string", "description": "The agreed day as YYYY-MM-DD, inside the window.", "default": "{{date}}"},
        "time": {"type": "string", "description": "The agreed time as HH:MM, 10:00 to 20:00.", "default": "{{time}}"}},
       "required": ["customer_id", "date", "time"]}}}},
     "pre_process_code": "try:\n    b = config.get('body')\n    if isinstance(b, dict) and isinstance(b.get('time'), str):\n        t = b['time'].strip().replace('.', ':')\n        if len(t) == 4 and t[1] == ':':\n            t = '0' + t\n        b['time'] = t[:5]\n    import datetime\n    HOL = ['2026-11-09', '2026-11-23', '2026-12-08', '2026-12-25', '2026-12-28']\n    now = datetime.datetime.strptime(str(vars.get('now'))[:16].replace(' ', 'T'), '%Y-%m-%dT%H:%M')\n    today = now.date()\n    nb = today + datetime.timedelta(days=1)\n    while nb.weekday() >= 5 or nb.isoformat() in HOL:\n        nb = nb + datetime.timedelta(days=1)\n    dd = str(b.get('date') or '')\n    tt = str(b.get('time') or '')\n    ok = '10:00' <= tt <= '20:00' and len(tt) == 5 and (dd == nb.isoformat() or (dd == today.isoformat() and tt > now.strftime('%H:%M')))\n    if not ok:\n        vars['cb_outside'] = 'yes'\n        b['date'] = 'outside-window'\n    else:\n        vars['cb_outside'] = 'no'\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['close_outcome'] = 'not_reached'\n        vars['close_reason'] = 'callback'\n        vars['call_state'] = 'callback_booked'\n        d['what_to_do_next'] = 'Booked. Thank them and say goodbye.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'Not booked. Ask once for another time inside the window.'\n    else:\n        result['what_to_do_next'] = 'Not booked. Ask once for another time inside the window.'\nexcept Exception:\n    pass\n"},
