  "identity": {
   "name": "identity",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Thank you. For security I need to ask you three questions. First, what is your date of birth?"},
   "on_enter_first_entry_only": true,
   "task_message": "Ask three security questions, one at a time, in this order: date of birth, then the postcode of the registered address, then the last four digits of the phone number on file. After each answer call verify_identity with field date_of_birth, postcode or phone_last4 and the answer. Send a date of birth as YYYY-MM-DD; a date given only as numbers is day, then month, then year. Send a postcode in capitals with one space before the last three characters. Send phone_last4 as four digits. Only the customer may answer. If the customer does not want to answer or asks what the call is about, explain once that the questions protect their account. Do not mention any account, debt or payment. If they ask for a human, first ask once whether you can help. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one answer. CALL it every time the customer answers a security question.", "parameters": {"type": "object", "properties": {
      "url": {"type": "string", "default": "https://bank-mock.invalid/f2-ostral/v1/verify_identity"},
      "method": {"type": "string", "default": "POST"},
      "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
      "body": {"type": "object", "properties": {
        "customer_id": {"type": "string", "default": "{{customer_id}}"},
        "field": {"type": "string", "enum": ["date_of_birth", "postcode", "phone_last4"], "description": "Which question was answered.", "default": "{{field}}"},
        "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD. postcode: capitals, one space before the last three characters, e.g. LS6 2HQ. phone_last4: four digits.", "default": "{{answer}}"}},
       "required": ["customer_id", "field", "answer"]}}}},
     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        f = b.get('field')\n        a = str(b.get('answer') or '').strip()\n        if f == 'postcode':\n            p = a.upper().replace(' ', '')\n            if len(p) > 3:\n                a = p[:-3] + ' ' + p[-3:]\n        elif f == 'phone_last4':\n            dg = ''.join(c for c in a if c.isdigit())\n            if len(dg) >= 4:\n                a = dg[-4:]\n        elif f == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                a = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\n        b['answer'] = a\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict):\n        if str(d.get('all_verified')).lower() == 'true':\n            vars['id_state'] = 'passed'\n            d['what_to_do_next'] = 'All questions passed. Say thank you in a few words.'\n        elif d.get('hint') == 'day_month_swapped':\n            d['what_to_do_next'] = 'Ask the customer to say the date of birth again with the month as a word. This does not count as a wrong answer.'\n        elif str(d.get('wrong_answers_left')) == '0':\n            vars['id_state'] = 'failed'\n            d['what_to_do_next'] = 'The check failed. Do not mention any account.'\n        elif str(d.get('verified')).lower() == 'true':\n            d['what_to_do_next'] = 'Correct. Ask the next question: after the date of birth the postcode of the registered address; after the postcode the last four digits of the phone number on file.'\n        elif str(d.get('ok')).lower() == 'false':\n            d['what_to_do_next'] = 'The answer could not be read. Ask for the same answer again.'\n        else:\n            d['what_to_do_next'] = 'That answer is wrong. Ask the same question once more.'\n    else:\n        result['what_to_do_next'] = 'The check did not work. Ask the same question again.'\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
